Object.assign(SNIP,{});PRESET_NOTES["l8"]={"Ví dụ: Đếm, tổng, trung bình": "Một vòng lặp làm được nhiều việc cùng lúc: đếm số dương và cộng tổng. Trung bình tính sau vòng lặp, nhớ ép sang double.", "Ví dụ: Lớn nhất và lớn nhì": "Gặp số lớn hơn m1: m1 cũ “xuống hạng” thành m2. Số bằng m1 (lần thứ hai gặp 9) bị bỏ qua nên lớn nhì là 7, khác lớn nhất.", "Ví dụ: Đoạn tăng liên tiếp dài nhất": "hienTai = độ dài đoạn tăng kết thúc tại i. Tiếp nối được (a[i] > a[i−1]) thì cộng 1, không thì bắt đầu lại từ 1. Vùng tô màu là đoạn tăng đang xét.", "Ví dụ: Giá trị xuất hiện nhiều nhất": "Lần duyệt thứ nhất đếm, lần duyệt thứ hai tìm ô đếm lớn nhất. Dùng > (không phải >=) nên khi hòa, giữ giá trị nhỏ hơn.", "Ví dụ: Có số âm không? Tất cả đều chẵn?": "“Có ít nhất một”: khởi tạo false, gặp một trường hợp thì đặt true. “Tất cả”: khởi tạo true, gặp một phản ví dụ thì đặt false."};EX_HINTS["l8"]=[["Dùng cờ coM2 cho biết đã có lớn nhì hay chưa, thay vì khởi tạo m2 bằng một số “rất nhỏ” dễ sai.", "Số bằng m1 thì bỏ qua; số lớn hơn m1 làm m1 cũ thành m2."], ["Chỉ cần nhớ số đứng trước, độ dài đoạn tăng kết thúc tại vị trí hiện tại, và độ dài tốt nhất.", "Không tăng (kể cả bằng nhau) thì đoạn mới bắt đầu với độ dài 1."], ["Khai báo mảng đếm toàn cục int cnt[100001]; (tự bằng 0, không lo tràn ngăn xếp).", "Duyệt cnt từ giá trị nhỏ tới lớn và chỉ đổi khi lớn hơn hẳn: tự động chọn giá trị nhỏ nhất khi hòa."]];
/* ===================== BÀI 8 · Duyệt mảng: đếm, tính tổng, tìm lớn nhất và nhỏ nhất ===================== */
/* Bài 8 · Duyệt mảng: đếm, tính tổng, tìm lớn nhất và nhỏ nhất
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const PR8=[{label:"Ví dụ: Đếm, tổng, trung bình",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> a = {7, -2, 4, 0, 9, -5, 3};\n    int dem = 0;\n    long long tong = 0;\n    for (int i = 0; i < (int)a.size(); i++) {\n        if (a[i] > 0) dem++;\n        tong += a[i];\n    }\n    cout << dem << \" so duong, tong = \" << tong << \", trung binh = \" << (double)tong / a.size() << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a",ptr:["i"]},{type:"vars",names:["dem","tong"]}],py:{code:"a = [7, -2, 4, 0, 9, -5, 3]\ndem = 0\ntong = 0\nfor i in range(len(a)):\n    if a[i] > 0:\n        dem += 1\n    tong += a[i]\nprint(dem, \"so duong, tong =\", tong, \", trung binh =\", round(tong / len(a), 5))",note:"Một vòng lặp làm được nhiều việc cùng lúc: đếm số dương và cộng tổng. Trung bình tính sau vòng lặp; / của Python luôn cho số thực."},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 7, -2, 4, 0, 9, -5, 3 };\n        int dem = 0;\n        long tong = 0;\n        for (int i = 0; i < a.Length; i++)\n        {\n            if (a[i] > 0) dem++;\n            tong += a[i];\n        }\n        double tb = (double)tong / a.Length;\n        Console.WriteLine($\"{dem} so duong, tong = {tong}, trung binh = {tb:F2}\");\n    }\n}",note:"Một vòng lặp làm được nhiều việc cùng lúc: đếm số dương và cộng tổng. Trung bình tính sau vòng lặp; ép (double) trước khi chia để không mất phần thập phân, rồi in 2 chữ số bằng {tb:F2}."}},{label:"Ví dụ: Lớn nhất và lớn nhì",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> a = {6, 2, 9, 4, 9, 7, 1};\n    int m1 = a[0], m2 = -1000000000;\n    for (int i = 1; i < (int)a.size(); i++) {\n        int x = a[i];\n        if (x > m1) {\n            m2 = m1;\n            m1 = x;\n        } else if (x < m1 && x > m2) {\n            m2 = x;\n        }\n    }\n    cout << \"Lon nhat \" << m1 << \", lon nhi \" << m2 << \"\\n\";\n    return 0;\n}",viz:[{type:"bars",of:"a",ptr:["i"]},{type:"vars",names:["x","m1","m2"]}],predict:[{line:12,v:"m1",val:true,q:"m1 sẽ thành giá trị nào? (bấm vào cột có giá trị đó)"}],py:{code:"a = [6, 2, 9, 4, 9, 7, 1]\nm1 = a[0]\nm2 = -1000000000\nfor i in range(1, len(a)):\n    x = a[i]\n    if x > m1:\n        m2 = m1\n        m1 = x\n    elif x < m1 and x > m2:\n        m2 = x\nprint(\"Lon nhat\", m1, \", lon nhi\", m2)",predict:[{line:8,v:"m1",val:true,q:"m1 sẽ thành giá trị nào? (bấm vào cột có giá trị đó)"}]},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 6, 2, 9, 4, 9, 7, 1 };\n        int m1 = a[0], m2 = -1000000000;\n        for (int i = 1; i < a.Length; i++)\n        {\n            int x = a[i];\n            if (x > m1)\n            {\n                m2 = m1;\n                m1 = x;\n            }\n            else if (x < m1 && x > m2)\n            {\n                m2 = x;\n            }\n        }\n        Console.WriteLine(\"Lon nhat \" + m1 + \", lon nhi \" + m2);\n    }\n}",predict:[{line:15,v:"m1",val:true,q:"m1 sẽ thành giá trị nào? (bấm vào cột có giá trị đó)"}]}},{label:"Ví dụ: Đoạn tăng liên tiếp dài nhất",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> a = {3, 5, 8, 2, 4, 6, 9, 1};\n    int hienTai = 1, tot = 1;\n    for (int i = 1; i < (int)a.size(); i++) {\n        if (a[i] > a[i - 1]) hienTai++;\n        else hienTai = 1;\n        if (hienTai > tot) tot = hienTai;\n    }\n    cout << \"Dai nhat: \" << tot << \"\\n\";\n    return 0;\n}",viz:[{type:"bars",of:"a",ptr:["i"],range:["i-hienTai+1","i"]},{type:"vars",names:["hienTai","tot"]}],py:{code:"a = [3, 5, 8, 2, 4, 6, 9, 1]\nhienTai = 1\ntot = 1\nfor i in range(1, len(a)):\n    if a[i] > a[i - 1]:\n        hienTai += 1\n    else:\n        hienTai = 1\n    if hienTai > tot:\n        tot = hienTai\nprint(\"Dai nhat:\", tot)"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 3, 5, 8, 2, 4, 6, 9, 1 };\n        int hienTai = 1, tot = 1;\n        for (int i = 1; i < a.Length; i++)\n        {\n            if (a[i] > a[i - 1]) hienTai++;\n            else hienTai = 1;\n            if (hienTai > tot) tot = hienTai;\n        }\n        Console.WriteLine(\"Dai nhat: \" + tot);\n    }\n}"}},{label:"Ví dụ: Giá trị xuất hiện nhiều nhất",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> a = {4, 1, 4, 2, 1, 4, 3};\n    vector<int> cnt(5, 0);\n    for (int x : a) cnt[x]++;\n    int best = 0;\n    for (int v = 1; v < 5; v++) {\n        if (cnt[v] > cnt[best]) best = v;\n    }\n    cout << best << \" xuat hien \" << cnt[best] << \" lan\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a"},{type:"cells",of:"cnt",ptr:["v","best"],label:"cnt[giá trị]"}],py:{code:"a = [4, 1, 4, 2, 1, 4, 3]\ncnt = [0] * 5\nfor x in a:\n    cnt[x] += 1\nbest = 0\nfor v in range(1, 5):\n    if cnt[v] > cnt[best]:\n        best = v\nprint(best, \"xuat hien\", cnt[best], \"lan\")"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 4, 1, 4, 2, 1, 4, 3 };\n        int[] cnt = new int[5];\n        foreach (int x in a) cnt[x]++;\n        int best = 0;\n        for (int v = 1; v < 5; v++)\n        {\n            if (cnt[v] > cnt[best]) best = v;\n        }\n        Console.WriteLine(best + \" xuat hien \" + cnt[best] + \" lan\");\n    }\n}"}},{label:"Ví dụ: Có số âm không? Tất cả đều chẵn?",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> a = {4, 8, 2, 6, 10};\n    bool coAm = false, tatCaChan = true;\n    for (int x : a) {\n        if (x < 0) coAm = true;\n        if (x % 2 != 0) tatCaChan = false;\n    }\n    cout << coAm << \" \" << tatCaChan << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a"},{type:"vars",names:["x","coAm","tatCaChan"]}],py:{code:"a = [4, 8, 2, 6, 10]\ncoAm = False\ntatCaChan = True\nfor x in a:\n    if x < 0:\n        coAm = True\n    if x % 2 != 0:\n        tatCaChan = False\nprint(coAm, tatCaChan)",note:"“Có ít nhất một”: khởi tạo False, gặp một trường hợp thì đặt True. “Tất cả”: khởi tạo True, gặp một phản ví dụ thì đặt False. Python có sẵn any(…) và all(…) làm đúng việc này."},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 4, 8, 2, 6, 10 };\n        bool coAm = false, tatCaChan = true;\n        foreach (int x in a)\n        {\n            if (x < 0) coAm = true;\n            if (x % 2 != 0) tatCaChan = false;\n        }\n        Console.WriteLine(coAm + \" \" + tatCaChan);\n    }\n}",note:"“Có ít nhất một”: khởi tạo false, gặp một trường hợp thì đặt true. “Tất cả”: khởi tạo true, gặp một phản ví dụ thì đặt false. C# in giá trị bool thành True/False. LINQ có sẵn a.Any(…) và a.All(…) làm đúng việc này."}}];
const sim8=makeSim2(document.getElementById("sim-l8"),{id:"s8",presets:PR8});
makeEx2(document.getElementById("ex-l8"),sim8,[{t:"Lớn nhì khác lớn nhất",d:"Đầu vào: n (1 ≤ n ≤ 10^5) rồi n số nguyên (|aᵢ| ≤ 10^9). Đầu ra: số lớn nhất trong các số nhỏ hơn hẳn giá trị lớn nhất; nếu mọi số bằng nhau thì in NONE.",tests:[{in:"7\n6 2 9 4 9 7 1",out:"7"},{in:"3\n5 5 5",out:"NONE"},{in:"1\n8",out:"NONE"},{in:"4\n-1 -5 -1 -3",out:"-3"},{in:"2\n1000000000 -1000000000",out:"-1000000000"}],start:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    // giữ m1 (lớn nhất) và m2 (lớn nhì, nhỏ hơn hẳn m1)\n    return 0;\n}",perf:{gen:n=>n+"\n"+Array.from({length:n},(_,i)=>((i*7919)%100003)).join(" "),ns:[1000,4000,16000],need:"n",limit:n=>16*n+100,why:"Một lần duyệt với hai biến là đủ; sắp xếp hoặc so mọi cặp đều tốn hơn."},py:{start:"n = int(input())\na = list(map(int, input().split()))\n# giữ m1 (lớn nhất) và m2 (lớn nhì, nhỏ hơn hẳn m1)",hints:["Dùng m2 = None nghĩa là “chưa có lớn nhì”, thay vì khởi tạo bằng một số “rất nhỏ” dễ sai.","Số bằng m1 thì bỏ qua; số lớn hơn m1 làm m1 cũ thành m2."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        int[] a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        // giữ m1 (lớn nhất) và m2 (lớn nhì, nhỏ hơn hẳn m1)\n    }\n}",hints:["Dùng cờ coM2 cho biết đã có lớn nhì hay chưa, thay vì khởi tạo m2 bằng một số “rất nhỏ” dễ sai.","Số bằng m1 thì bỏ qua; số lớn hơn m1 làm m1 cũ thành m2.","Hai nhánh của ? : phải cùng kiểu: m2.ToString() và \"NONE\" đều là string."]}},{t:"Đoạn tăng liên tiếp dài nhất",d:"Đầu vào: n (1 ≤ n ≤ 10^5) rồi n số nguyên. Đầu ra: độ dài của đoạn liên tiếp dài nhất trong đó mỗi số lớn hơn hẳn số đứng ngay trước nó.",tests:[{in:"8\n3 5 8 2 4 6 9 1",out:"4"},{in:"1\n7",out:"1"},{in:"4\n5 5 5 5",out:"1"},{in:"5\n1 2 3 4 5",out:"5"},{in:"6\n9 7 5 3 1 2",out:"2"}],start:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    // hienTai = độ dài đoạn tăng kết thúc tại vị trí đang xét\n    return 0;\n}",perf:{gen:n=>n+"\n"+Array.from({length:n},(_,i)=>((i*7919)%100003)).join(" "),ns:[1000,4000,16000],need:"n",limit:n=>18*n+100,why:"Thử mọi đoạn là O(n²) hoặc O(n³). Mỗi phần tử chỉ cần xét một lần."},py:{start:"n = int(input())\na = list(map(int, input().split()))\n# hienTai = độ dài đoạn tăng kết thúc tại vị trí đang xét",hints:["Chỉ cần nhớ độ dài đoạn tăng kết thúc tại vị trí hiện tại và độ dài tốt nhất.","Không tăng (kể cả bằng nhau) thì đoạn mới bắt đầu với độ dài 1."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        int[] a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        // hienTai = độ dài đoạn tăng kết thúc tại vị trí đang xét\n    }\n}",hints:["Chỉ cần nhớ độ dài đoạn tăng kết thúc tại vị trí hiện tại và độ dài tốt nhất.","Không tăng (kể cả bằng nhau) thì đoạn mới bắt đầu với độ dài 1."]}},{t:"Giá trị xuất hiện nhiều nhất",d:"Đầu vào: n (1 ≤ n ≤ 10^5) rồi n số nguyên trong khoảng 0..100000. Đầu ra: giá trị xuất hiện nhiều lần nhất và số lần của nó; nếu hòa, chọn giá trị nhỏ nhất.",tests:[{in:"7\n4 1 4 2 1 4 3",out:"4 3"},{in:"4\n2 1 2 1",out:"1 2"},{in:"1\n100000",out:"100000 1"},{in:"5\n0 0 0 5 5",out:"0 3"}],start:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    // mảng đếm cnt[0..100000]\n    return 0;\n}",perf:{gen:n=>n+"\n"+Array.from({length:n},(_,i)=>(i*7919)%100001).join(" "),ns:[1000,4000,16000],need:"n",limit:n=>9*n+400000,why:"Đếm số lần xuất hiện của từng giá trị bằng vòng lặp lồng nhau là O(n²). Dùng mảng đếm."},py:{start:"n = int(input())\na = list(map(int, input().split()))\n# danh sách đếm cnt[0..100000]",hints:["Tạo danh sách đếm cnt = [0] * 100001.","Duyệt cnt từ giá trị nhỏ tới lớn và chỉ đổi khi lớn hơn hẳn: tự động chọn giá trị nhỏ nhất khi hòa.","Đếm bằng a.count(v) cho từng v là O(n · V): quá chậm."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        int[] a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        // mảng đếm cnt[0..100000]\n    }\n}",hints:["Tạo mảng đếm int[] cnt = new int[100001]; (C# tự gán mọi phần tử bằng 0).","Duyệt cnt từ giá trị nhỏ tới lớn và chỉ đổi khi lớn hơn hẳn: tự động chọn giá trị nhỏ nhất khi hòa.","Đếm bằng vòng lặp riêng cho từng giá trị v là O(n · V): quá chậm."]}}]);

makeQuiz("quiz8","score8",[{"q": "Tìm số lớn nhất và lớn nhì của n số bằng hai biến tốn bao nhiêu?", "o": ["O(1)", "O(n)", "O(n log n)", "O(n²)"], "a": 1, "e": "Một lần duyệt, mỗi phần tử so sánh vài lần: O(n). Sắp xếp sẽ tốn O(n log n)."}, {"q": "Kiểm tra “mọi phần tử đều dương”, biến cờ nên khởi tạo bằng?", "o": ["false", "true", "0", "-1"], "a": 1, "e": "“Tất cả” khởi tạo true và đặt false khi gặp phản ví dụ."}, {"q": "Dãy 1 3 2 4 6 8 5. Đoạn tăng liên tiếp dài nhất có độ dài?", "o": ["3", "4", "5", "7"], "a": 1, "e": "Đoạn 2 4 6 8 dài 4."}, {"q": "Khi nào dùng được mảng đếm cnt[giá trị]?", "o": ["Khi các giá trị là số thực", "Khi các giá trị là số nguyên nằm trong khoảng không quá lớn", "Khi n nhỏ", "Luôn luôn"], "a": 1, "e": "Kích thước mảng đếm bằng khoảng giá trị; giá trị tới 10⁹ thì không khai báo nổi (cần bảng băm, Chương 6)."}]);

